macro_rules! deps {
    () => {
        UnificationTable!();
        ConstVidKey!();
        TypeOutlivesConstraint!();
        PredicateObligation!();
        RegionConstraintStorage!();
        Snapshot!();
        At!();
        InferCtxtUndoLogs!();
        ProjectionCacheStorage!();
        OpaqueTypeStorage!();
        TypeVariableStorage!();
        InferCtxt!();
    };
}

macro_rules! InferCtxtInner {
    () => {
        deps!();
        # [doc = " This type contains all the things within `InferCtxt` that sit within a"] # [doc = " `RefCell` and are involved with taking/rolling back snapshots. Snapshot"] # [doc = " operations are hot enough that we want only one call to `borrow_mut` per"] # [doc = " call to `start_snapshot` and `rollback_to`."] # [derive (Clone)] pub struct InferCtxtInner < 'tcx > { undo_log : InferCtxtUndoLogs < 'tcx > , # [doc = " Cache for projections."] # [doc = ""] # [doc = " This cache is snapshotted along with the infcx."] projection_cache : traits :: ProjectionCacheStorage < 'tcx > , # [doc = " We instantiate `UnificationTable` with `bounds<Ty>` because the types"] # [doc = " that might instantiate a general type variable have an order,"] # [doc = " represented by its upper and lower bounds."] type_variable_storage : type_variable :: TypeVariableStorage < 'tcx > , # [doc = " Map from const parameter variable to the kind of const it represents."] const_unification_storage : ut :: UnificationTableStorage < ConstVidKey < 'tcx > > , # [doc = " Map from integral variable to the kind of integer it represents."] int_unification_storage : ut :: UnificationTableStorage < ty :: IntVid > , # [doc = " Map from floating variable to the kind of float it represents."] float_unification_storage : ut :: UnificationTableStorage < ty :: FloatVid > , # [doc = " Tracks the set of region variables and the constraints between them."] # [doc = ""] # [doc = " This is initially `Some(_)` but when"] # [doc = " `resolve_regions_and_report_errors` is invoked, this gets set to `None`"] # [doc = " -- further attempts to perform unification, etc., may fail if new"] # [doc = " region constraints would've been added."] region_constraint_storage : Option < RegionConstraintStorage < 'tcx > > , # [doc = " A set of constraints that regionck must validate."] # [doc = ""] # [doc = " Each constraint has the form `T:'a`, meaning \"some type `T` must"] # [doc = " outlive the lifetime 'a\". These constraints derive from"] # [doc = " instantiated type parameters. So if you had a struct defined"] # [doc = " like the following:"] # [doc = " ```ignore (illustrative)"] # [doc = " struct Foo<T: 'static> { ... }"] # [doc = " ```"] # [doc = " In some expression `let x = Foo { ... }`, it will"] # [doc = " instantiate the type parameter `T` with a fresh type `$0`. At"] # [doc = " the same time, it will record a region obligation of"] # [doc = " `$0: 'static`. This will get checked later by regionck. (We"] # [doc = " can't generally check these things right away because we have"] # [doc = " to wait until types are resolved.)"] # [doc = ""] # [doc = " These are stored in a map keyed to the id of the innermost"] # [doc = " enclosing fn body / static initializer expression. This is"] # [doc = " because the location where the obligation was incurred can be"] # [doc = " relevant with respect to which sublifetime assumptions are in"] # [doc = " place. The reason that we store under the fn-id, and not"] # [doc = " something more fine-grained, is so that it is easier for"] # [doc = " regionck to be sure that it has found *all* the region"] # [doc = " obligations (otherwise, it's easy to fail to walk to a"] # [doc = " particular node-id)."] # [doc = ""] # [doc = " Before running `resolve_regions_and_report_errors`, the creator"] # [doc = " of the inference context is expected to invoke"] # [doc = " [`InferCtxt::process_registered_region_obligations`]"] # [doc = " for each body-id in this map, which will process the"] # [doc = " obligations within. This is expected to be done 'late enough'"] # [doc = " that all type inference variables have been bound and so forth."] region_obligations : Vec < TypeOutlivesConstraint < 'tcx > > , # [doc = " The outlives bounds that we assume must hold about placeholders that"] # [doc = " come from instantiating the binder of coroutine-witnesses. These bounds"] # [doc = " are deduced from the well-formedness of the witness's types, and are"] # [doc = " necessary because of the way we anonymize the regions in a coroutine,"] # [doc = " which may cause types to no longer be considered well-formed."] region_assumptions : Vec < ty :: ArgOutlivesPredicate < 'tcx > > , # [doc = " `-Znext-solver`: Successfully proven goals during HIR typeck which"] # [doc = " reference inference variables and get reproven in case MIR type check"] # [doc = " fails to prove something."] # [doc = ""] # [doc = " See the documentation of `InferCtxt::in_hir_typeck` for more details."] hir_typeck_potentially_region_dependent_goals : Vec < PredicateObligation < 'tcx > > , # [doc = " Caches for opaque type inference."] opaque_type_storage : OpaqueTypeStorage < 'tcx > , }
    };
}

InferCtxtInner!();